export function rrzLookup(brand, model, wCm){
  var tbl = brand==="somfy" ? RRZ_SOMFY : RRZ_PREMIUM;
  var row = tbl[model];
  if(!row) return null;
  var idx = RRZ_WIDTHS.findIndex(function(w){ return w >= wCm; });
  if(idx<0) idx = RRZ_WIDTHS.length-1;
  var price = row[idx];
  if(price==null) return null;
  return {price: price, upToWidth: RRZ_WIDTHS[idx]};
}

export function lookup(val,obj){
  var keys=Object.keys(obj).map(Number).sort(function(a,b){return a-b;});
  var k=keys.find(function(k){return k>=val;})||keys[keys.length-1];
  return {p:obj[k],k:k};
}

export function calc(p){
  var c=p.c||{},par=p.par||{};
  var fabP=p.fabMan!=null?p.fabMan:(p.fabP!=null?p.fabP:null);
  var fabW=p.fabW||0;
  var total=0,lines=[],warn=null;
  // ── ZUŻYCIE MATERIAŁÓW (usage) ───────────────────────────────────────────
  // calc() liczylo metry biezace i powierzchnie szycia od zawsze, ale zapisywalo
  // je wylacznie jako tekst w `lines`. Bez liczby nie da sie pomnozyc zuzycia
  // przez cene ZAKUPU, a faktury od Vadaina i LaurAles sa zbiorcze dla wielu
  // zlecen — wiec kosztu nie da sie przypisac do realizacji z samej faktury.
  // Ten obiekt niczego nie zmienia w cenie sprzedazy; jest czystym dopiskiem.
  var usage={
    // Nazwa tkaniny siedzi na produkcie (p.fabName), nie w konfiguracji c —
    // ustawia ja sf() w ProdCard. fabManName to tkanina wpisana recznie
    // (spoza cennika), dla ktorej ceny zakupu z definicji nie znamy.
    fabName:(p.fabName||null), fabManName:(p.fabManName||null),
    fab2Name:(p.fab2Name||null),
    fabMb:0, fab2Mb:0, liningMb:0,
    fabSell:0,              // wartosc SPRZEDAZY tkaniny (do wyliczenia mechSell)
    sewMb:0, sewM2:0,       // zasłony liczy sie na mb, rolety na m2
    sewSell:0               // wartosc SPRZEDAZY szycia
  };

  if(p.type==="zaslona"||p.type==="firana"){
    var wCm=par.wCm||0,hCm=par.hCm||0;
    var belka=fabW,mars=+(c.mars||"1.5"),szycie=(c.sz==="wave"||c.model==="wave")?(c.waveMask==="tak"?150:120):(c.model==="falda")?110:100;
    var dekro=c.dekro==="tak",hM=hCm/100;
    var podszewka=c.podszewka==="tak";
    if(!wCm||!(p.panels||[]).length||fabP==null)return{total:0,lines:[],warn:fabP==null&&wCm?"Wybierz tkanin\u0119":null};
    (p.panels||[]).forEach(function(pn){
      var pw=pn.w||0;if(!pw){lines.push(pn.side+": wpisz szerokość (cm)");return;}var pwZ=pw+20,pm=pw/100,z,kt,ks,kp,koszt;
      // Wysoko\u015b\u0107 per panel (komplet z r\xf3\u017cn\u0105 wysoko\u015bci\u0105 L/P), domy\u015blnie par.hCm
      var phCm=pn.h||hCm,hM=phCm/100;
      var useA2=belka>0&&phCm+20>belka&&c.tasiemkaStojaco!=="tak";
      if(useA2){
        var pg=Math.ceil((belka/mars)/10)*10-20,lp=Math.ceil((pwZ/pg)*2)/2;
        z=Math.ceil((lp*hM+0.2)*10)/10;kt=+(z*fabP).toFixed(2);
        var sv=hM<=3?100:hM<=3.7?130:hM<=4.9?170:230;
        ks=dekro?+(z*sv).toFixed(2):+(lp*250).toFixed(2);
      }else{
        z=Math.ceil((pm*mars+0.2)*10)/10;kt=+(z*fabP).toFixed(2);
        var sv2=hM<=3?100:hM<=3.7?130:hM<=4.9?170:230;
        ks=dekro?+(z*sv2).toFixed(2):+(z*szycie).toFixed(2);
      }
      kp=podszewka?+(z*80+ks*0.5).toFixed(2):0;
      koszt=kt+ks+kp;total+=koszt;
      usage.fabMb+=z; usage.fabSell+=kt;
      usage.sewMb+=z; usage.sewSell+=ks;
      if(podszewka){usage.liningMb+=z; usage.fabSell+=z*80; usage.sewSell+=ks*0.5;}
      lines.push(pn.side+" "+pw+"cm"+(pn.h&&pn.h!==hCm?" \u00d7 h"+pn.h+"cm":"")+" \u00b7 "+z+"mb \u2192 "+koszt.toFixed(2).replace(".",",")+" z\u0142"+(podszewka?" (w tym podszewka)":""));
    });
  }else if(p.type==="zaluzja"){
    var wCm=par.wCm||0,lCm=par.lCm||0;
    var jt=c.jt||"al25";
    if(!wCm||!lCm)return{total:0,lines:[],warn:null};
    var jzColorList=jt==="al25"?JZ_AL25_COLORS:jt.indexOf("al")===0?JZ_AL50_COLORS:jt==="ba27"?JZ_BA27_COLORS:jt.indexOf("ba")===0?JZ_BA50_COLORS:jt.indexOf("bs")===0?JZ_BS50_COLORS:null;
    var al50Color=null;
    if(jzColorList&&c.jzColor){
      al50Color=jzColorList.find(function(col){return col.v===c.jzColor;});
      if(al50Color&&wCm>al50Color.maxWidth)return{total:0,lines:[],warn:"Szerokość "+wCm+"cm niedostępna dla koloru "+al50Color.l+" (maks. "+al50Color.maxWidth+" cm)."};
    }
    var res=jzLookup(jt,wCm,lCm);
    if(!res)return{total:0,lines:[],warn:"Wymiary poza zakresem cennika."};
    total=res.price;
    var jzBaseZ=total;
    if(al50Color&&al50Color.surchargePct>0){
      var sur=+(total*al50Color.surchargePct/100).toFixed(2);
      total+=sur;
      lines.push("Dopłata kolor "+al50Color.l+" +"+al50Color.surchargePct+"% → +"+sur.toFixed(2)+" zł");
    }
    // dopłaty
    if(c.bezinw==="tak"){
      var bDop=120; // stawka ryczałtowa — zastępuje dawną kwotę zależną od materiału i Prowadzenie boczne
      total+=bDop;
      lines.push("Monta\u017c bezinwazyjny +"+bDop.toFixed(2)+" z\u0142");
    }
    var tGroup=jzTasWidthGroup(jt);
    if(c.tasiemkaColor&&tGroup){
      if(wCm<60){warn=(warn?warn+" | ":"")+"Tasiemka niedostępna dla szer. < 60 cm.";}
      else{
        var tasCol=JZ_TASIEMKA_COLORS.find(function(col){return col.v===c.tasiemkaColor;});
        if(tasCol&&tasCol[tGroup]===10){
          var tSur=+(jzBaseZ*10/100).toFixed(2);
          total+=tSur;
          lines.push("Dopłata kolor tasiemki "+tasCol.l+" +10% → +"+tSur.toFixed(2)+" z\u0142");
        }
      }
    }
    lines.push(JZ_LABELS[jt]+" "+wCm+"\xd7"+lCm+"cm \u2192 "+res.price+" z\u0142");
    // strefy
    var pow=(wCm/100)*(lCm/100);
    var z=JZ_ZONES[jt]||{};
    if(z.blue&&pow>=z.blue)warn="Strefa niebieska ("+pow.toFixed(2)+"m\xb2) \u2014 wymagana obs\u0142uga elektryczna.";
    else if(z.red&&pow>=z.red)warn="Strefa czerwona ("+pow.toFixed(2)+"m\xb2) \u2014 ograniczona gwarancja.";
    if(c.jzMode==="auto"){
      var mot=JZALUZJA_MOTORS.find(function(m){return m.id===c.jzMotorId;});
      var rem=JZALUZJA_REMOTES.find(function(r){return r.id===c.jzRemoteId;});
      if(mot){total+=mot.price;lines.push("Silnik: "+mot.label+" +"+mot.price.toFixed(2)+" zł");}
      if(rem){total+=rem.price;lines.push("Pilot: "+rem.label+" +"+rem.price.toFixed(2)+" zł");}
    }
  }else if(p.type==="roleta"){
    var wCm=par.wCm||0,hCm=par.hCm||0;
    if(!wCm||!hCm)return{total:0,lines:[],warn:null};
    // Nowy system: c.rModel (relax/print/back/podszewka/front/cascade/duo)
    var rModel=c.rModel||null;
    if(!rModel)return{total:0,lines:[],warn:"Wybierz model rolety"};
    var tkan=fabP!=null?fabP:160;
    // ── Zużycie tkaniny ──────────────────────────────────────────────
    // Szerokość: szerokość rolety + 2×10 cm na boki
    var tkanWcm=wCm+20;
    // Wysokość: h + 5cm rzep góra + 10cm podwinięcie dół + tunele×2cm
    var iloscTuneli=Math.floor(hCm/23);
    var tkanHcm=hCm+5+10+iloscTuneli*2;
    var pow=parseFloat(((tkanWcm/100)*(tkanHcm/100)).toFixed(3));
    var powInfo="tkanina "+tkanWcm+"\xd7"+tkanHcm+"cm ("+iloscTuneli+" tuneli)";
    var powSzycie=parseFloat(((wCm/100)*(hCm/100)).toFixed(3));
    var rr;
    if(c.rSystem==="bez_mechanizmu"){
      // Bez mechanizmu: szycie = w*h m2 * 200zl, tkanina = (w+30)/100 mb * fabP
      var tkanWcmMat=wCm+30;
      var kosztSzycia=parseFloat((powSzycie*200).toFixed(2));
      var kosztTkaniny=parseFloat(((tkanWcmMat/100)*tkan).toFixed(2));
      total=parseFloat((kosztSzycia+kosztTkaniny).toFixed(2));
      usage.fabMb+=tkanWcmMat/100; usage.fabSell+=kosztTkaniny;
      usage.sewM2+=powSzycie;      usage.sewSell+=kosztSzycia;
      lines.push("Roleta bez mech. "+rModel+" "+wCm+"\xd7"+hCm+"cm \xb7 szycie "+powSzycie+"m\xb2\xd7200z\u0142 + tkanina "+(tkanWcmMat/100).toFixed(2)+"mb\xd7"+tkan+"z\u0142");
    }else if(rModel==="duo"){
      // Duo: dwie różne tkaniny (np. firankowa + zaciemniająca)
      var tkan2=p.fab2Man!=null?p.fab2Man:(p.fab2P!=null?p.fab2P:null);
      if(tkan2==null)return{total:0,lines:[],warn:"Wybierz drugą tkaninę (Duo)"};
      rr=c.rSystem==="polautomatyczny"?lookup(wCm,RPOLAUTO_DUO):lookup(wCm,RDUO);
      var kosztSzyciaDuo=parseFloat((powSzycie*200*2).toFixed(2));
      var kosztTkan1Duo=parseFloat(((tkanWcm/100)*tkan).toFixed(2));
      var kosztTkan2Duo=parseFloat(((tkanWcm/100)*tkan2).toFixed(2));
      var mechCostDuo=c.rSystem==="polautomatyczny"?parseFloat(rr.p.toFixed(2)):parseFloat((rr.p*2).toFixed(2));
      total=mechCostDuo+kosztSzyciaDuo+kosztTkan1Duo+kosztTkan2Duo;
      usage.fabMb+=tkanWcm/100;  usage.fab2Mb+=tkanWcm/100;
      usage.fabSell+=kosztTkan1Duo+kosztTkan2Duo;
      usage.sewM2+=powSzycie*2;  usage.sewSell+=kosztSzyciaDuo;
      lines.push("Roleta Duo "+wCm+"\xd7"+hCm+"cm \xb7 "+pow+"m\xb2 \xb7 "+powInfo);
      lines.push("  Szycie: "+powSzycie+"m\xb2\xd7200z\u0142 \xd7 2 tkaniny");
      lines.push("  Tkanina 1: "+(tkanWcm/100).toFixed(2)+"mb\xd7"+tkan.toFixed(0)+"z\u0142");
      lines.push("  Tkanina 2: "+(tkanWcm/100).toFixed(2)+"mb\xd7"+tkan2.toFixed(0)+"z\u0142");
    }else{
      // Szycie = pow * 200, tkanina = tkanWcm/100 mb * tkan
      var kosztSzycia=parseFloat((powSzycie*200).toFixed(2));
      var kosztTkaniny=parseFloat(((tkanWcm/100)*tkan).toFixed(2));
      rr=lookup(wCm,RCITY);
      total=parseFloat((rr.p*2).toFixed(2))+kosztSzycia+kosztTkaniny;
      usage.fabMb+=tkanWcm/100; usage.fabSell+=kosztTkaniny;
      usage.sewM2+=powSzycie;   usage.sewSell+=kosztSzycia;
      if(c.rSystem==="elektryk"){
        rr=lookup(wCm,REL);
        total=parseFloat((rr.p*2).toFixed(2))+kosztSzycia+kosztTkaniny;
      }else if(c.rSystem==="polautomatyczny"){
        rr=lookup(wCm,RPOLAUTO);
        total=parseFloat(rr.p.toFixed(2))+kosztSzycia+kosztTkaniny;
      }
      lines.push("Roleta rzymska "+rModel+" "+wCm+"\xd7"+hCm+"cm \xb7 szycie "+powSzycie+"m\xb2\xd7200z\u0142 + tkanina "+(tkanWcm/100).toFixed(2)+"mb\xd7"+tkan.toFixed(0)+"z\u0142");
    }
    // Podszewka (+80zł/mb tkaniny + 50% do kosztu szycia)
    if(c.rPodszewka==="tak"&&c.rSystem!=="bez_mechanizmu"){
      var kosztPodszSzycia=rModel==="duo"?+(powSzycie*200*2*0.5).toFixed(2):+(powSzycie*200*0.5).toFixed(2);
      var kosztPodszTkan=+((tkanWcm/100)*80).toFixed(2);
      var podszTot=+(kosztPodszSzycia+kosztPodszTkan).toFixed(2);
      total+=podszTot;
      usage.liningMb+=tkanWcm/100;
      usage.fabSell+=kosztPodszTkan; usage.sewSell+=kosztPodszSzycia;
      lines.push("+ Podszewka "+(tkanWcm/100).toFixed(2)+"mb\xd780z\u0142 + 50% szycia \u2192 +"+podszTot.toFixed(2)+" z\u0142");
    }
    // Maskownice/boczki
    if(c.rMask==="tak"){total+=50;lines.push("+ Boczki/maskownice +50 z\u0142");}
    // Rolety rzymskie dachowe
    if(c.rDachowe==="tak"){total+=320;lines.push("+ Rolety rzymskie dachowe +320 z\u0142");}
    // Montaż bezinwazyjny
    if(c.rBezinw==="tak"){total+=60;lines.push("+ Monta\u017c bezinwazyjny +60 z\u0142");}
  }else if(p.type==="shadow"){
    var wCm=par.wCm||0,hCm=par.hCm||0;
    if(!wCm||!hCm)return{total:0,lines:[],warn:null};
    var sg=c.sgrup||"C";
    var res=rsShadowLookup(sg,wCm,hCm);
    if(!res)return{total:0,lines:[],warn:"Wymiary poza zakresem cennika (maks. 300\xd7300 cm)."};
    total=res.price;
    lines.push("Roleta Shadow RM (Gr."+sg+") "+res.widthUsed+"\xd7"+res.heightUsed+"cm \u2192 "+res.price+" z\u0142");
    // Profil montażowy
    if(c.sprofil==="tak"){var pv=rsSuppLookup(RS_PROFIL,wCm);total+=pv;lines.push("+ Profil monta\u017cowy +"+pv+" z\u0142");}
    // Obciążnik
    if(c.sobcTyp&&c.sobcTyp!=="A"){
      var obcTbl={B:RS_OB_B,C:RS_OB_C,D:RS_OB_D}[c.sobcTyp];
      if(obcTbl){var ov=rsSuppLookup(obcTbl,wCm);total+=ov;lines.push("+ Obci\u0105\u017cnik Typ "+c.sobcTyp+" +"+ov+" z\u0142");}
    }else if(c.sobcTyp==="A"){
      lines.push("+ Obci\u0105\u017cnik Typ A (standardowy, w cenie)");
    }
    // Maskownica
    if(c.smask&&c.smask!=="brak"){var mv=RS_MASKS[c.smask]||0;if(mv){total+=mv;var mcl=RS_MASK_COLORS.find(function(x){return x.k===c.smaskKolor;});var mklbl=mcl?" ("+mcl.l+")":"";lines.push("+ Maskownica "+c.smask+mklbl+" +"+mv.toFixed(2)+" z\u0142");}}
    // Zestaw żyłkowy
    if(c.szylko==="tak"){total+=RS_ZESTAW_ZYLKOWY;lines.push("+ Zestaw do prowadzenia \u017cy\u0142kowego +"+RS_ZESTAW_ZYLKOWY.toFixed(2)+" z\u0142");}
    // Obciążnik łańcuszka
    if(c.slanc==="tak"){total+=RS_LANCUSZEK;lines.push("+ Ozdobny obci\u0105\u017cnik \u0142a\u0144cuszka +"+RS_LANCUSZEK.toFixed(2)+" z\u0142");}
    // Napęd
    if(c.smotor){
      var mot=RS_MOTORS.find(function(m){return m.id===c.smotor;});
      if(mot){total+=mot.price;lines.push("+ Nap\u0119d "+mot.label+" +"+mot.price+" z\u0142");}
    }
    // Pilot/centralka
    if(c.sremotes&&c.sremotes.length){
      c.sremotes.forEach(function(rid){
        var rem=RS_REMOTES.find(function(r){return r.id===rid;});
        if(rem){total+=rem.price;lines.push("+ "+rem.label+" +"+rem.price+" z\u0142");}
      });
    }
  }else if(p.type==="inny"){
    // Cena za szt. (c.innyCena, string — dopuszcza przecinek) x ilość (par.qty)
    var inCena=+(String(c.innyCena==null?"":c.innyCena).replace(",","."))||0,inQty=par.qty||1;
    if(!inCena)return{total:0,lines:[],warn:null};
    total=inCena*inQty;
    lines.push((p.innyNazwa||"Inny")+" "+formatPLN(inCena)+"/szt."+(inQty>1?" x"+inQty:""));
  }else if(p.type==="szyna"){
    var lenCm=par.len||0,arc=par.arc||0,pts=par.pts||0,qty=par.qty||1;
    if(!lenCm)return{total:0,lines:[],warn:null};
    var lenMb=lenCm/100;
    var baz;
    if(c.ks==="wave"){baz=parseFloat((lenMb*100).toFixed(2));}
    else baz=parseFloat((lenMb*80).toFixed(2));
    total=baz*qty+parseFloat((arc*100).toFixed(2))+parseFloat((pts*100).toFixed(2));
    lines.push("KS "+(c.ks||"flex")+" "+lenCm+"cm ("+lenMb.toFixed(2)+"mb)"+(qty>1?" x"+qty:""));
    if(c.km==="sciana")warn="\u015acienny \u2014 dolicz uchwyty \u015bcienne.";
  }else if(p.type==="plisa"){
    var wMm=par.wMm||0,hMm=par.hMm||0;
    if(!wMm||!hMm)return{total:0,lines:[],warn:null};
    var plRes=plisaLookup(wMm,hMm);
    if(!plRes)return{total:0,lines:[],warn:"Wymiary poza zakresem cennika (maks. 1300\xd72500 mm)."};
    total=plRes.price;
    var plColl=PLISA_FABRICS.find(function(f){return f.name===c.plKolekcja;});
    var plFabLabel=plColl?(plColl.name+(c.plKolorKod?" "+c.plKolorKod:"")):(c.plKolekcjaManual?c.plKolekcjaManual+(c.plKolorManual?" "+c.plKolorManual:""):null);
    lines.push("Plisa okienna (Gr.IV) "+plRes.widthUsed+"\xd7"+plRes.heightUsed+"mm \u2192 "+plRes.price+" z\u0142");
    if(plFabLabel)lines.push("Tkanina: "+plFabLabel);
    var plOspCol=PLISA_OSPRZET_KOLORY.find(function(k){return k.v===c.plKolorOsprzetu;});
    if(plOspCol){
      lines.push("Kolor osprz\u0119tu: "+plOspCol.l);
      if(plOspCol.drewno){
        var plDop=lookup(wMm,PLISA_OSPRZET_DOPLATA).p;
        total+=plDop;
        lines.push("+ Dop\u0142ata osprz\u0119t drewnopodobny +"+plDop+" z\u0142");
      }
    }
    if(c.plDrabinka==="tak"){
      var plDrab=plisaDrabinkaDoplata(wMm,hMm);
      total+=plDrab;
      lines.push("+ Drabinka podtrzymuj\u0105ca tkanin\u0119 +"+plDrab+" z\u0142");
    }
  }else if(p.type==="karnisz"){
    var lenK=par.len||0,pt=par.pt||0,arc=par.arc||0,qty=par.qty||1;
    if(!lenK)return{total:0,lines:[],warn:null};
    var st=c.km==="universal"?KUNIV:KSLIM;
    var rk=lookup(lenK,st);
    total=(rk.p+(KN[c.kn||"am75"]||0)+(KP[c.kp||"brak"]||0)+(KP[c.kc||"brak"]||0))*qty+pt*250+arc*318;
    lines.push("Karnisz "+(c.km||"slim").toUpperCase()+" do "+rk.k+"cm"+(qty>1?" x"+qty:""));
  }else if(p.type==="prestige_round"||p.type==="prestige_square"){
    var lenP=parseInt(par.len)||0,qty=par.qty||1;
    if(!lenP)return{total:0,lines:[],warn:null};
    var seria=p.type==="prestige_round"?"ROUND":"SQUARE";
    var TAB =p.type==="prestige_round"?PRESTIGE_ROUND:PRESTIGE_SQUARE;
    var TW60=p.type==="prestige_round"?PRESTIGE_ROUND_W60:PRESTIGE_SQUARE_W60;
    var TW80=p.type==="prestige_round"?PRESTIGE_ROUND_W80:PRESTIGE_SQUARE_W80;
    var TT  =p.type==="prestige_round"?PRESTIGE_ROUND_TANDEM:PRESTIGE_SQUARE_TANDEM;
    var nap=c.pn||"am75_3w";
    var motorTab=TAB[nap]||TAB.am75_3w;
    var bazaP=motorTab[lenP]||0;
    var lineSum=bazaP;
    var napLabel=(PRESTIGE_NAPEDY.find(function(x){return x.v===nap;})||{l:nap}).l;
    lines.push("Karnisz Prestige "+seria+" "+lenP+"cm — "+napLabel+(qty>1?" x"+qty:""));
    // WAVE (dopłata)
    if(c.wave==="w60"){var w=TW60[lenP]||0;lineSum+=w;if(w>0)lines.push("Dopłata WAVE 60 mm");}
    else if(c.wave==="w80"){var w=TW80[lenP]||0;lineSum+=w;if(w>0)lines.push("Dopłata WAVE 80 mm");}
    // Tandem
    if(c.tandem){var t=TT[nap]||0;lineSum+=t;if(t>0)lines.push("Tandem (rozsuwanie dwustronne synchroniczne)");}
    // Pilot
    var pil=PRESTIGE_PILOTY.find(function(x){return x.v===(c.pp||"brak");});
    if(pil&&pil.c>0){lineSum+=pil.c;lines.push(pil.l);}
    // Centralka
    var cen=PRESTIGE_CENTRALKI.find(function(x){return x.v===(c.pcn||"brak");});
    if(cen&&cen.c>0){lineSum+=cen.c;lines.push(cen.l);}
    // Ładowarka (tylko dla akumulatora)
    if(nap==="am75_aku"&&c.lad){lineSum+=PRESTIGE_LADOWARKA;lines.push("Ładowarka do silnika akumulatorowego");}
    total=lineSum*qty;
  }else if(p.type==="karnisz_dek"){
    // p.kdRozmiar: 20|30, p.kdSzyny: [{dlugosc:160,qty:1},...], p.kdAkc: {id:qty}, p.kdKolor: id
    var kdR=p.kdRozmiar||20;
    var kdSzT=KD_SZYNY[kdR]||KD_SZYNY[20];
    var kdSzL=p.kdSzyny||[];
    var kdT=0;
    kdSzL.forEach(function(s){
      var cena=kdSzT[s.len]||0;
      var q=s.qty||1;
      kdT+=cena*q;
      if(cena>0) lines.push("Szyna "+kdR+"mm / "+s.len+"cm"+(q>1?" x"+q:"")+" = "+formatPLN(cena*q));
    });
    if(kdSzL.length>0){
      var kdZ=KD_ZASLEPKI[kdR]||0;
      kdT+=kdZ*2;
      lines.push("Za\u015blepki "+kdR+"mm x2 = "+formatPLN(kdZ*2));
    }
    var kdA=p.kdAkc||{};
    KD_AKCESORIA.forEach(function(a){
      var q=parseInt(kdA[a.id])||0;
      if(q>0){kdT+=a.cena*q;lines.push(a.label+(q>1?" x"+q:"")+" = "+formatPLN(a.cena*q));}
    });
    total=kdT;
  }
  // Reszta ceny (mechanizmy rolet, zaluzje, karnisze, szyny, plisy, doplaty)
  // to pozycje kupowane gotowe — ich koszt wyliczamy z mnoznika, patrz costOf().
  usage.mechSell=Math.max(0,+(total-usage.fabSell-usage.sewSell).toFixed(2));
  usage.fabMb=+(usage.fabMb.toFixed(3));
  usage.fab2Mb=+(usage.fab2Mb.toFixed(3));
  usage.liningMb=+(usage.liningMb.toFixed(3));
  usage.sewMb=+(usage.sewMb.toFixed(3));
  usage.sewM2=+(usage.sewM2.toFixed(3));
  usage.fabSell=+(usage.fabSell.toFixed(2));
  usage.sewSell=+(usage.sewSell.toFixed(2));
  return{total:total,lines:lines,warn:warn,usage:usage};
}

// ── KOSZT WŁASNY POZYCJI ────────────────────────────────────────────────────
// Liczy koszt z ZUŻYCIA, nie z faktury. Faktury za tkaninę i szycie są zbiorcze
// dla wielu zleceń, więc przypisanie ich do realizacji jest niemożliwe — ale
// zużycie każdej pozycji jest znane co do metra, a cena zakupu tkaniny siedzi
// w cenniku (FABRICS.zakup, nadpisywalna przez catalog_items.purchase_price).
//
// rates:
//   sewCurtainMb — ile płacimy szwalni za mb szycia zasłony/firany
//   sewRomanM2   — ile płacimy szwalni za m² rolety rzymskiej
//   liningMb     — cena zakupu podszewki za mb
//   mechDivisor  — dzielnik ceny detalicznej pozycji gotowych (mechanizmy,
//                  żaluzje, karnisze, szyny KS). Marża 100%, więc koszt = detal / 2.
// Zwraca null dla składników, dla których brakuje danych — świadomie, żeby
// niepełna marża była widoczna jako niepełna, a nie zaniżona o ciche zero.
export function costOf(usage,rates,fabricLookup){
  if(!usage)return null;
  var r=rates||{};
  // Pozycje gotowe (mechanizmy rolet, zaluzje, karnisze, szyny KS) sprzedajemy
  // tak samo jak szycie: cena dla klienta = nasz koszt x 2.
  var divisor=+(r.mechDivisor)||2;
  var missing=[];
  var fabCost=0;
  function unitCost(name,mb,labelIfMissing){
    if(!mb)return 0;
    var f=name&&fabricLookup?fabricLookup(name):null;
    if(!f||f.zakup==null){missing.push(labelIfMissing);return 0;}
    return mb*(+f.zakup||0);
  }
  fabCost+=unitCost(usage.fabName,usage.fabMb,"cena zakupu tkaniny"+(usage.fabName?" \u201e"+usage.fabName+"\u201d":""));
  fabCost+=unitCost(usage.fab2Name,usage.fab2Mb,"cena zakupu tkaniny"+(usage.fab2Name?" \u201e"+usage.fab2Name+"\u201d":""));
  var liningCost=0;
  if(usage.liningMb){
    if(r.liningMb==null){missing.push("cena zakupu podszewki");}
    else liningCost=usage.liningMb*(+r.liningMb||0);
  }
  // Koszt szycia — dwa tryby. Domyslny: procent wartosci szycia z wyceny
  // (sewQuotePct=100 oznacza "sprzedajemy szycie po kosztach, marza jest
  // w tkaninie"). Tryb dokladny wlacza sie po wpisaniu stawki zl/mb lub zl/m2
  // i ma pierwszenstwo. Dzieki temu marza liczy sie od razu, bez konfiguracji.
  var sewCost=0;
  // Szycie sprzedajemy z marza 100% (cena dla klienta = nasz koszt x 2),
  // wiec koszt to polowa wartosci szycia z wyceny.
  var sewPct=(r.sewQuotePct==null)?50:(+r.sewQuotePct||0);
  var sewExact=(r.sewCurtainMb!=null&&usage.sewMb)||(r.sewRomanM2!=null&&usage.sewM2);
  if(sewExact){
    if(usage.sewMb){
      if(r.sewCurtainMb==null){missing.push("stawka szycia zas\u0142on (z\u0142/mb)");}
      else sewCost+=usage.sewMb*(+r.sewCurtainMb||0);
    }
    if(usage.sewM2){
      if(r.sewRomanM2==null){missing.push("stawka szycia rolet (z\u0142/m\u00b2)");}
      else sewCost+=usage.sewM2*(+r.sewRomanM2||0);
    }
  }else{
    sewCost=usage.sewSell*sewPct/100;
  }
  var mechCost=usage.mechSell?usage.mechSell/divisor:0;
  return {
    fabric:+(fabCost.toFixed(2)),
    lining:+(liningCost.toFixed(2)),
    sewing:+(sewCost.toFixed(2)),
    hardware:+(mechCost.toFixed(2)),
    total:+((fabCost+liningCost+sewCost+mechCost).toFixed(2)),
    missing:missing,
    complete:missing.length===0
  };
}

export function mg(a,b){return Object.assign({},a,b);}

export const IST ={padding:"16px 18px",fontSize:17,border:"1.5px solid var(--bd2)",borderRadius:10,background:"var(--bg)",color:"var(--t1)",width:"100%",minHeight:56,boxSizing:"border-box",transition:"border-color .15s"};


// ── INLINE EDIT COMPONENT ────────────────────────────────────────────────
export function InlineEdit(p){
  // p: {value, onSave, style, inputStyle}
  var es=useState(false),editing=es[0],setEditing=es[1];
  var vs=useState(p.value),val=vs[0],setVal=vs[1];
  React.useEffect(function(){setVal(p.value);},[p.value]);
  function confirm(){
    if(val.trim()) p.onSave(val.trim());
    setEditing(false);
  }
  if(editing){
    return ce("span",{style:{display:"inline-flex",alignItems:"center",gap:4}},
      ce("input",{autoFocus:true,value:val,
        onClick:function(ev){ev.stopPropagation();},
        onChange:function(ev){setVal(ev.target.value);},
        onKeyDown:function(ev){
          if(ev.key==="Enter")confirm();
          if(ev.key==="Escape"){setVal(p.value);setEditing(false);}
        },
        onBlur:confirm,
        style:Object.assign({},{fontSize:16,fontWeight:500,border:"none",borderBottom:"2px solid var(--gr)",outline:"none",background:"transparent",color:"var(--t1)",padding:"2px 4px",minWidth:120,maxWidth:"90vw"},p.inputStyle||{})
      })
    );
  }
  return ce("span",{style:Object.assign({},{display:"inline-flex",alignItems:"center",gap:5,cursor:"pointer"},p.style||{})},
    ce("span",{},p.value),
    ce("span",{
      onClick:function(ev){ev.stopPropagation();setEditing(true);},
      title:"Edytuj",
      style:{fontSize:18,color:"var(--t3)",opacity:0.75,lineHeight:1,padding:"6px 8px",borderRadius:8,
             border:"0.5px solid transparent",transition:"all .15s",cursor:"pointer",
             ":hover":{opacity:1}}
    },"\u270f\ufe0f")
  );
}

