function _offerPDFHtmlCore(client,rows,montaz,offerNotes,validUntil,discount,visitFee){
  montaz=montaz||0;
  var montazMode=montaz.mode||"percent";
  var montazInputValue=montaz.mode?montaz.value:montaz;
  montaz=montazMode==="amount"?0:montazInputValue;
  discount=(+discount>0)?roundTo10(+discount):0;
  visitFee=(+visitFee>0)?roundTo10(+visitFee):0;
  offerNotes=offerNotes||"";
  if(!rows||!rows.length)return null;
  var total=rows.reduce(function(a,r){return a+(+r.total||0);},0);
  var now=new Date();
  var dateStr=now.toLocaleDateString("pl-PL");
  var validStr=(((validUntil instanceof Date)&&!isNaN(validUntil))?validUntil:new Date(now.getTime()+30*24*3600*1000)).toLocaleDateString("pl-PL");
  var offerNo=getPDFOfferNumber(client);

  var roomGroups=[];
  var roomIndex={};
  rows.forEach(function(r){
    var key=r.room||"Inne";
    if(roomIndex[key]==null){roomIndex[key]=roomGroups.length;roomGroups.push({room:key,rows:[]});}
    roomGroups[roomIndex[key]].rows.push(r);
  });

  var tablesHTML=roomGroups.map(function(g){
    var gRows=g.rows.map(function(r){
      return [
        r.qtyUnit||((r.qty!=null?r.qty:1)+" "+(r.unit||"")),
        r.name,
        r.modelSzycia||"-",
        r.tkaninaKolor||"-",
        r.producent||"-",
        r.szerokosc||"-",
        r.wysokosc||"-",
        r.podzial||"-",
        (+r.total||0).toFixed(2).replace(".",",")+" zł"
      ];
    });
    var gTotal=g.rows.reduce(function(a,r){return a+(+r.total||0);},0);
    gRows.push(["","<strong>Razem: "+g.room+"</strong>","","","","","","",
      "<strong>"+gTotal.toFixed(2).replace(".",",")+" zł</strong>"
    ]);
    return makeTableHTML(["Ilość","Produkt","Model szycia","Tkanina / Kolor / Osprzęt","Producent","Szerokość","Wysokość","Podział / Sterowanie","Cena brutto"],gRows,g.room,['6%','21%','10%','16%','9%','8%','8%','11%','11%']);
  }).join("\n");

  var userNotesHTML=offerNotes
    ?'<div class="notes"><strong>Uwagi:</strong><br>'+String(offerNotes).replace(/</g,"&lt;").replace(/\n/g,"<br>")+'</div>'
    :'';

  var extraStyles=`
    body{font-size:13px;}
    table{font-size:12px;border-collapse:collapse!important;border:1.5px solid #999!important;}
    caption{font-size:11px;}
    th{font-size:10px;padding:5px 8px;border:1px solid #999!important;background:#ebebeb!important;}
    td{padding:5px 8px;font-size:12px;line-height:1.5;border:1px solid #bbb!important;vertical-align:top;}
    tr:nth-child(even) td{background:#fafaf8;}
  `;

  var html=`<!DOCTYPE html><html lang="pl"><head><meta charset="UTF-8"><title>Wycena szczegółowa ${offerNo}</title>${pdfStyles().replace('@media print{@page{size:A4;','@media print{@page{size:A4 landscape;').replace('</style>',extraStyles+'</style>')}</head><body>
  <div class="header">
    <div><img src="${LOGO_PDF_G}" style="height:50px;width:auto;" alt="Porter Design"/></div>
    <div style="text-align:right"><div style="font-size:20px;font-weight:700">Wycena szczegółowa nr ${offerNo}</div>
      <div style="font-size:9px;color:#6b6b66;margin-top:4px">Data wystawienia: ${dateStr} &nbsp;|&nbsp; Ważne do: ${validStr}</div>
    </div>
  </div>
  <div class="meta">
    <div class="meta-block"><h4>Nabywca</h4>
      <p><strong>${client.name}</strong><br>${client.addr||""}</p>
    </div>
  </div>
  ${tablesHTML}
  <div class="sum-box"><span class="label">Do zapłaty</span><span class="amount">${total.toFixed(2).replace(".",",")} PLN</span></div>
  ${userNotesHTML}
  <div class="notes">Niniejszy dokument nie jest fakturą w rozumieniu ustawy z dnia 11 marca 2004 r. o podatku od towarów i usług.</div>
  <div class="footer"><span>${SELLER.name} | ${SELLER.city}</span><span>Strona 1</span></div>
  </body></html>`;
  var montazVal=montazMode==="amount"?roundTo10(montazInputValue): (montaz>0?roundTo10(total*montaz):0);
  var totalWithMontaz=montazVal>0?roundTo10(total+montazVal):total;
  var deduction=discount+visitFee;
  var finalTotal=Math.max(0,roundTo10(totalWithMontaz-deduction));
  var extraBreakdown='';
  if(montazVal>0){
    extraBreakdown+='<div style="margin:4mm 0 3mm;padding:10px 14px;background:#eeece9;border-radius:8px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:12px;color:#1a1a18;">Monta\u017c dekoracji okiennych ('+(montazMode==="amount"?montazVal.toFixed(2).replace(".",",")+" zł":Math.round(montaz*100)+"%")+'):</span><span style="font-size:13px;font-weight:700;color:#1a1a18;">'+montazVal.toFixed(2).replace(".",",")+' z\u0142</span></div>'
      +'<div style="margin-bottom:3mm;padding:10px 14px;background:#e8e8e4;border-radius:8px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:12px;color:#555;font-weight:600;">\u0141\u0105cznie bez monta\u017cu:</span><span style="font-size:14px;font-weight:700;color:#555;">'+total.toFixed(2).replace(".",",")+' z\u0142</span></div>';
  }
  if(discount>0){
    extraBreakdown+='<div style="margin-bottom:3mm;padding:10px 14px;background:#f5ede0;border-radius:8px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:12px;color:#1a1a18;">Przyznany rabat:</span><span style="font-size:13px;font-weight:700;color:#1a1a18;">\u2212'+discount.toFixed(2).replace(".",",")+' z\u0142</span></div>';
  }
  if(visitFee>0){
    extraBreakdown+='<div style="margin-bottom:3mm;padding:10px 14px;background:#f5ede0;border-radius:8px;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:12px;color:#1a1a18;">Koszt wizyty (odliczony od zam\u00f3wienia):</span><span style="font-size:13px;font-weight:700;color:#1a1a18;">\u2212'+visitFee.toFixed(2).replace(".",",")+' z\u0142</span></div>';
  }
  if(extraBreakdown){
    html=html.replace('<div class="sum-box">',extraBreakdown+'<div class="sum-box">');
  }
  if(montazVal>0||deduction>0){
    var finalLabel=montazVal>0?'\u0141\u0105cznie z monta\u017cem':'\u0141\u0105cznie';
    html=html.replace('<span class="label">Do zapłaty</span><span class="amount">'+total.toFixed(2).replace(".",",")+' PLN</span>','<span class="label">'+finalLabel+'</span><span class="amount">'+finalTotal.toFixed(2).replace(".",",")+' PLN</span>');
  }
  return html;
}

export function buildOfferPDFHtml(client,comm,montaz,offerNotes,validUntil,discount,visitFee){
  comm=comm||0;
  var rows=buildOfferDetailRows(client);
  if(!rows.length)return null;
  if(comm>0){
    rows=rows.map(function(r){
      var newTotal=roundTo10(r.total*(1+comm));
      return Object.assign({},r,{total:newTotal,cenaJedn:newTotal});
    });
  }
  return _offerPDFHtmlCore(client,rows,montaz,offerNotes,validUntil,discount,visitFee);
}

// Wariant przyjmujący już gotowe (i ewentualnie ręcznie doedytowane na ekranie
// podglądu) wiersze — używany przez ekran "Wycena szczegółowa — podgląd".
export function buildOfferPDFHtmlFromRows(client,rows,montaz,offerNotes,validUntil,discount,visitFee){
  return _offerPDFHtmlCore(client,rows,montaz,offerNotes,validUntil,discount,visitFee);
}

export function generateOfferPDF(client,comm,montaz,discount,visitFee){
  var offerNotes=window.prompt("Uwagi do oferty (opcjonalne):","") || "";
  if(offerNotes===null)return;
  var html=buildOfferPDFHtml(client,comm,montaz,offerNotes,null,discount,visitFee);
  if(!html){alert("Brak wycenionych produktów.");return;}
  openPDFWindow(html, getPDFOfferNumber(client),{landscape:true});
}

export function generateOfferPDFFromRows(client,rows,montaz,offerNotes,validUntil,discount,visitFee){
  var html=buildOfferPDFHtmlFromRows(client,rows,montaz,offerNotes,validUntil,discount,visitFee);
  if(!html){alert("Brak wycenionych produktów.");return;}
  var offerNo=getPDFOfferNumber(client);
  var offerTotal=(rows||[]).reduce(function(a,r){return a+(+r.total||0);},0);
  // Kwota zapisywana w offers.total_gross musi zawierać montaż — inaczej faktura
  // wystawiana "na podstawie oferty" (ScreenInvoices.applyOfferAmount liczy % od
  // total_gross) nie doliczy montażu, mimo że PDF oferty go pokazuje.
  var montazParam=montaz||0;
  var montazModeV=montazParam.mode||"percent";
  var montazInputV=montazParam.mode?montazParam.value:montazParam;
  var montazPctV=montazModeV==="amount"?0:montazInputV;
  var montazAmount=montazModeV==="amount"?roundTo10(montazInputV):(montazPctV>0?roundTo10(offerTotal*montazPctV):0);
  persistOffer(client,offerNo,"szczegolowa",offerTotal+montazAmount,validUntil,offerNotes,discount);
  openPDFWindow(html, offerNo,{landscape:true});
}

// ── Suppliers for karnisze / szyny ─────────────────────────────────────────
export const KARNISZ_SUPPLIERS =[
  {key:"marcin_dekor", label:"Marcin Dekor"},
  {key:"forest_polska",label:"Forest Polska, ul. Poloneza 89, 02-826 Warszawa"}
];

// ── Geometria szyny giętej w jeden łuk (cięciwa + strzałka) ──────────────
// chord = rozstaw końców łuku (cm), depth = wysięg/strzałka w najgłębszym punkcie (cm)
// Zwraca {R, len, deg} (cm, cm, stopnie) lub null gdy dane niepełne.
export function arcGeom(chord,depth){
  var c=+chord||0,h=+depth||0;
  if(c<=0||h<=0)return null;
  var R=(c*c/4+h*h)/(2*h);
  var ang=4*Math.atan(2*h/c); // pełny kąt środkowy w radianach
  return {R:R,len:R*ang,deg:ang*180/Math.PI};
}
export function arcDesc(par){
  par=par||{};
  var g=arcGeom(par.arcChord,par.arcDepth);
  if(!g&&!par.arc)return "";
  var parts=["gi\u0119ta w \u0142uk"];
  if(par.arcChord)parts.push("ci\u0119ciwa "+par.arcChord+" cm");
  if(par.arcDepth)parts.push("g\u0142\u0119b. "+par.arcDepth+" cm");
  if(g)parts.push("R\u2248"+Math.round(g.R)+" cm");
  return parts.join(", ");
}

export function buildKarniszRows(client){
  var rows=[];
  (client.rooms||[]).forEach(function(r){
    (r.windows||[]).forEach(function(w){
      (w.products||[]).forEach(function(p){
        if(p.type!=="karnisz"&&p.type!=="szyna"&&p.type!=="prestige_round"&&p.type!=="prestige_square")return;
        var pc=p.c||{},par=p.par||{};
        var typLabel;
        if(p.type==="karnisz"){
          typLabel="Karnisz elektryczny "+(pc.km||"slim").toUpperCase();
        }else if(p.type==="prestige_round"){
          typLabel="Karnisz Prestige ROUND ("+(pc.pn||"am75_3w")+")";
        }else if(p.type==="prestige_square"){
          typLabel="Karnisz Prestige SQUARE ("+(pc.pn||"am75_3w")+")";
        }else{
          typLabel="Szyna KS "+(pc.ks||"flex");
        }
        var len=par.len||0;
        var res=calc(p);
        var isKarnisz=(p.type==="karnisz"||p.type==="prestige_round"||p.type==="prestige_square");
        rows.push({
          room:r.name,
          win:w.name,
          type:typLabel,
          len:len,
          qty:par.qty||1,
          arc:par.arc||0,
          arcDepth:par.arcDepth||null,
          arcChord:par.arcChord||null,
          pts:par.pt||par.pts||0,
          motorSide:isKarnisz?(pc.motorSide||"lewo"):null,
          motorType:isKarnisz?(pc.motorType||"kurtyna"):null,
          supplier:p.karniszSupplier||"",
          total:res.total||0,
          lines:(res.lines||[]).join("; ")
        });
      });
    });
  });
  return rows;
}

// Buduje HTML zamówienia karniszy/szyn z już gotowych (ewentualnie ręcznie
// doedytowanych na ekranie podglądu) wierszy, pogrupowanych wg dostawcy.
export function buildKarniszPDFHtmlFromRows(client,rows){
  if(!rows||!rows.length)return null;
  var now=new Date();var dateStr=now.toLocaleDateString("pl-PL");

  var bySupplier={};
  KARNISZ_SUPPLIERS.forEach(function(s){bySupplier[s.key]=[];});
  rows.forEach(function(r){
    var key=(r.supplier&&bySupplier[r.supplier]!==undefined)?r.supplier:"marcin_dekor";
    bySupplier[key].push(r);
  });

  var activeSups=KARNISZ_SUPPLIERS.filter(function(s){return bySupplier[s.key].length>0;});
  if(!activeSups.length)return null;

  var supplierSections=activeSups.map(function(sup,si){
    var supRows=bySupplier[sup.key];
    var tableRows=supRows.map(function(r){
      var motorDesc=r.motorSide?(String(r.motorSide).charAt(0).toUpperCase()+String(r.motorSide).slice(1))+(r.motorType?" / "+(String(r.motorType).charAt(0).toUpperCase()+String(r.motorType).slice(1)):""):"–";
      return [
        r.roomWin||((r.room||"")+" / "+(r.win||"")),
        r.type,
        r.len?r.len+"cm":"-",
        (+r.qty||0)>1?r.qty+" szt.":"1 szt.",
        r.arc?r.arc+" mb":"–",
        (function(){var g=arcGeom(r.arcChord,r.arcDepth);return (r.arcDepth?r.arcDepth+" cm":"–")+(r.arcChord?"<br><span style=\"font-size:8px;color:#6b6b66\">ci\u0119ciwa "+r.arcChord+" cm"+(g?", R\u2248"+Math.round(g.R)+" cm":"")+"</span>":"");})(),
        r.pts?r.pts+" szt.":"–",
        motorDesc,
        (+r.total||0)>0?(+r.total).toFixed(2).replace(".",",")+" zł":"–"
      ];
    });

    var tableHTML=makeTableHTML(
      ["Pom. / Okno","Typ","D\u0142ugo\u015b\u0107","Ilo\u015b\u0107","Gi\u0119cie \u0142uk","G\u0142\u0119b. \u0142uku","Gi\u0119cie pkt","Silnik / Typ","Warto\u015b\u0107"],
      tableRows,
      "Pozycje do zam\xf3wienia"
    );

    var pageBreak=si>0?"<div style=\"page-break-before:always;padding-top:10mm;\"></div>":"";

    return pageBreak+"\n    <div class=\"supplier-header\">\n      <div class=\"supplier-name\">"+sup.label+"</div>\n      <div class=\"supplier-meta\">Zamawiaj\u0105cy: <strong>"+SELLER.name+"</strong>  |  Tel.: "+SELLER.tel+"  |  E-mail: "+SELLER.email+"</div>\n      <div class=\"supplier-meta\">Klient ko\u0144cowy: <strong>"+client.name+"</strong>"+(client.addr?" \u2014 "+client.addr:"")+"  |  Data: "+dateStr+"</div>\n    </div>\n    "+tableHTML+"\n    <div class=\"notes\" style=\"margin-top:4mm\">Termin dostawy: _________________ &nbsp;&nbsp;&nbsp; Forma p\u0142atno\u015bci: _________________</div>";
  }).join("");

  var extraStyles="\n    .supplier-header{background:#f2f2ef;border:0.5px solid #c8c8c4;border-radius:4px;padding:8px 12px;margin-bottom:5mm;}\n    .supplier-name{font-size:14px;font-weight:700;color:#1a1a18;margin-bottom:3px;letter-spacing:0.03em;}\n    .supplier-meta{font-size:9px;color:#6b6b66;margin-top:2px;}\n  ";

  return "<!DOCTYPE html><html lang=\"pl\"><head><meta charset=\"UTF-8\"><title>Zam\xf3wienie karnisz\xf3w \u2014 "+client.name+"</title>"+pdfStyles().replace("</style>",extraStyles+"</style>")+"</head><body>"
    +"<div class=\"header\"><div><div class=\"logo-text\">PORTER<br>DESIGN</div><div class=\"logo-sub\">Dekoracje okienne</div></div>"
    +"<div style=\"text-align:right\"><div style=\"font-size:18px;font-weight:700\">Zam\xf3wienie karnisz\xf3w / szyn</div>"
    +"<div style=\"font-size:9px;color:#6b6b66;margin-top:4px\">Klient: <strong>"+client.name+"</strong> &nbsp;|&nbsp; Data: "+dateStr+" &nbsp;|&nbsp; Dostawc\xf3w: "+activeSups.length+"</div></div></div>"
    +supplierSections
    +"<div class=\"footer\" style=\"margin-top:8mm\"><span>"+SELLER.name+" | "+SELLER.city+"</span><span>Generowano: "+dateStr+"</span></div>"
    +"</body></html>";
}

export function generateKarniszOrderPDFFromRows(client,rows){
  var html=buildKarniszPDFHtmlFromRows(client,rows);
  if(!html){alert("Brak pozycji.");return;}
  openPDFWindow(html,"zamowienie-karnisz");
}

export function generateKarniszOrderPDF(client){
  var rows=buildKarniszRows(client);
  if(!rows.length){alert("Brak karniszów / szyn do zamówienia.");return;}

  // Collect rows without a supplier assigned
  var pending=rows.filter(function(r){return !r.supplier;});

  function proceedWithPDF(){
    var html=buildKarniszPDFHtmlFromRows(client,rows);
    if(!html){alert("Brak pozycji.");return;}
    openPDFWindow(html,"zamowienie-karnisz");
  } // end proceedWithPDF

  // If all rows already have suppliers, go straight to PDF
  if(!pending.length){proceedWithPDF();return;}

  // Build a touch-friendly dialog to assign supplier per unassigned item
  var dlg=document.createElement("dialog");
  dlg.style.cssText="border:none;border-radius:14px;padding:24px 20px;max-width:400px;width:92%;box-shadow:0 8px 40px rgba(0,0,0,0.22);font-family:inherit;";

  var pidx=0;
  function showSupplierPick(){
    if(pidx>=pending.length){dlg.close();document.body.removeChild(dlg);proceedWithPDF();return;}
    var r=pending[pidx];
    var btns=KARNISZ_SUPPLIERS.map(function(s){
      return '<button data-key="'+s.key+'" style="display:block;width:100%;padding:14px 16px;border-radius:8px;border:1.5px solid #c8c8c4;background:#fff;font-size:14px;font-weight:600;cursor:pointer;text-align:left;margin-bottom:10px;">'+s.label+'</button>';
    }).join('');
    dlg.innerHTML='<div style="font-size:12px;color:#888;margin-bottom:6px;font-weight:600;letter-spacing:0.04em;text-transform:uppercase;">Dostawca ('+(pidx+1)+'/'+pending.length+')</div>'
      +'<div style="font-weight:700;font-size:15px;margin-bottom:4px">'+r.room+' / '+r.win+'</div>'
      +'<div style="font-size:13px;color:#555;margin-bottom:20px">'+r.type+(r.len?' — '+r.len+' cm':'')+'</div>'
      +btns
      +'<button data-key="cancel" style="display:block;width:100%;padding:10px;border-radius:8px;border:none;background:none;font-size:13px;color:#888;cursor:pointer;">Anuluj</button>';
    dlg.querySelectorAll("button").forEach(function(btn){
      btn.addEventListener("click",function(){
        var key=btn.getAttribute("data-key");
        if(key==="cancel"){dlg.close();document.body.removeChild(dlg);return;}
        r.supplier=key;
        pidx++;
        showSupplierPick();
      });
    });
  }
  document.body.appendChild(dlg);
  dlg.showModal();
  showSupplierPick();
}

// ── PDF: Szyny do montażu (lista dla montażysty) ────────────────────────────
export function buildRailsRows(client){
  var rows=[];
  (client.rooms||[]).forEach(function(room){
    (room.windows||[]).forEach(function(win){
      (win.products||[]).forEach(function(p){
        if(p.type!=="szyna"&&p.type!=="karnisz"&&p.type!=="prestige_round"&&p.type!=="prestige_square"&&p.type!=="karnisz_dek")return;
        var pc=p.c||{},par=p.par||{};
        var typLabel;
        if(p.type==="karnisz"){
          typLabel="Karnisz el. "+(pc.km==="univ"?"Universal":(pc.km||"Slim").toUpperCase());
        }else if(p.type==="prestige_round"){
          typLabel="Karnisz Prestige ROUND";
        }else if(p.type==="prestige_square"){
          typLabel="Karnisz Prestige SQUARE";
        }else if(p.type==="karnisz_dek"){
          typLabel="Karnisz dekoracyjny";
        }else{
          var ksMode=pc.ks||"flex";
          typLabel="Szyna KS "+(ksMode==="wave"?"Wave":ksMode==="manual"?"Manualna":"Flex");
        }
        var len=par.len||0;
        var qty=par.qty||1;
        if(!len)return;
        var aDesc=arcDesc(par);
        if(aDesc)typLabel+=" \u2014 "+aDesc;
        rows.push({room:room.name||"",win:win.name||"",type:typLabel,len:len,qty:qty});
      });
    });
  });
  return rows;
}

// Buduje HTML "Szyny do montażu" z już gotowych (ewentualnie ręcznie
// doedytowanych na ekranie podglądu) wierszy, pogrupowanych wg pomieszczeń.
export function buildRailsInstallHtmlFromRows(client,rows){
  if(!rows||!rows.length)return null;
  var now=new Date();var dateStr=now.toLocaleDateString("pl-PL");

  var roomGroups=[];
  var roomIndex={};
  rows.forEach(function(r){
    var key=r.room||"Inne";
    if(roomIndex[key]==null){roomIndex[key]=roomGroups.length;roomGroups.push({room:key,items:[]});}
    roomGroups[roomIndex[key]].items.push(r);
  });

  var extraStyles="\n    body{font-size:13px;}\n    .room-header{background:#2c2c2a;color:#fff;padding:7px 12px;font-size:12px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;border-radius:4px;margin:5mm 0 2mm;}\n    table{width:100%;border-collapse:collapse;margin-bottom:3mm;}\n    th{background:#f2f2ef;font-size:11px;font-weight:700;padding:6px 10px;text-align:left;border-bottom:1.5px solid #c8c8c4;}\n    td{padding:6px 10px;font-size:12px;border-bottom:1px solid #e8e8e4;vertical-align:top;}\n    tr:last-child td{border-bottom:none;}\n    .len-cell{font-size:14px;font-weight:700;color:#1a1a18;}\n    .qty-badge{display:inline-block;background:#eeece9;color:#555;font-size:10px;font-weight:700;padding:1px 6px;border-radius:10px;margin-left:6px;}\n    .summary-box{margin-top:8mm;background:#f7f7f5;border:1px solid #c8c8c4;border-radius:6px;padding:8px 14px;font-size:11px;color:#555;}\n    .footer{margin-top:8mm;display:flex;justify-content:space-between;font-size:9px;color:#a8a8a4;border-top:0.5px solid #e0e0dc;padding-top:4mm;}\n  ";

  var roomSections="";
  var totalItems=0;
  roomGroups.forEach(function(rg){
    var trows=rg.items.map(function(it){
      var qtyStr=(+it.qty||0)>1?'<span class="qty-badge">x'+it.qty+'</span>':"";
      return "<tr>"
        +"<td>"+rg.room+"</td>"
        +"<td>"+it.win+"</td>"
        +"<td>"+it.type+"</td>"
        +"<td class=\"len-cell\">"+it.len+" cm"+qtyStr+"</td>"
        +"</tr>";
    }).join("");
    totalItems+=rg.items.length;
    roomSections+='<div class="room-header">'+rg.room+'</div>'
      +'<table><thead><tr><th>Pomieszczenie</th><th>Okno / miejsce</th><th>Rodzaj</th><th>D\u0142ugo\u015b\u0107</th></tr></thead><tbody>'+trows+"</tbody></table>";
  });

  return '<!DOCTYPE html><html lang="pl"><head><meta charset="UTF-8"><title>Szyny do monta\u017cu</title>'
    +pdfStyles().replace('</style>',extraStyles+'</style>')
    +'</head><body>'
    +'<div class="header">'
    +'<div><img src="'+LOGO_PDF_G+'" style="height:50px;width:auto;" alt="Porter Design"/></div>'
    +'<div style="text-align:right"><div style="font-size:20px;font-weight:700">\uD83D\uDD29 Szyny do monta\u017cu</div>'
    +'<div style="font-size:11px;color:#6b6b66;margin-top:4px">Klient: <strong>'+client.name+'</strong></div>'
    +'<div style="font-size:10px;color:#a8a8a4;margin-top:2px">Wydrukowano: '+dateStr+'</div>'
    +'</div></div>'
    +roomSections
    +'<div class="summary-box">Pozycji szyn / karniszów: <strong>'+totalItems+'</strong></div>'
    +'<div class="footer"><span>'+SELLER.name+' \u2014 tylko do u\u017cytku wewn\u0119trznego</span><span>'+dateStr+'</span></div>'
    +'</body></html>';
}

export function generateRailsInstallPDFFromRows(client,rows){
  var html=buildRailsInstallHtmlFromRows(client,rows);
  if(!html){alert("Brak szyn / karniszów do wydruku.");return;}
  openPDFWindow(html,'szyny-montaz');
}

export function generateRailsInstallPDF(client){
  var rows=buildRailsRows(client);
  var html=buildRailsInstallHtmlFromRows(client,rows);
  if(!html){alert("Brak szyn / karniszów do wydruku.");return;}
  openPDFWindow(html,'szyny-montaz');
}



